from pathlib import Path
p=Path('/home/ubuntu/kentankclient/src/App.tsx')
s=p.read_text()

s=s.replace("type Business = { email: string; phone: string; whatsapp: string; location: string }\n", "type Business = { email: string; phone: string; whatsapp: string; location: string }\ntype Contact = { id: number; label: string; contact_type: 'phone' | 'whatsapp' | 'sms' | 'email'; value: string; display_value?: string | null; active: boolean; sort_order: number }\n")
s=s.replace("function Logo({ compact = false }: { compact?: boolean }) { return <div className={`brand ${compact ? 'brand-compact' : ''}`}>", "function contactHref(contact: Contact) { const value = contact.value.trim(); if (contact.contact_type === 'whatsapp') return `https://wa.me/${value.replace(/\\D/g, '')}`; if (contact.contact_type === 'sms') return `sms:${value.replace(/\\s/g, '')}`; if (contact.contact_type === 'phone') return `tel:${value.replace(/\\s/g, '')}`; return `mailto:${value}` }\nfunction ContactActions({ contacts, compact = false }: { contacts: Contact[]; compact?: boolean }) { const active = contacts.filter(contact => contact.active).slice(0, compact ? 2 : 4); if (!active.length) return null; return <div className={`contact-actions ${compact ? 'contact-actions-compact' : ''}`}>{active.map(contact => <a key={contact.id} className={`contact-action contact-action-${contact.contact_type}`} href={contactHref(contact)} target={contact.contact_type === 'whatsapp' ? '_blank' : undefined} rel={contact.contact_type === 'whatsapp' ? 'noreferrer' : undefined}>{contact.label}<small>{contact.display_value || contact.value}</small></a>)}</div> }\nfunction Logo({ compact = false }: { compact?: boolean }) { return <div className={`brand ${compact ? 'brand-compact' : ''}`}>")

s=s.replace("const [view, setView] = useState<View>('home'); const [products, setProducts] = useState<Product[]>([]); const [banners, setBanners] = useState<Banner[]>([]); const [categories, setCategories] = useState<Category[]>([]); const [business, setBusiness]", "const [view, setView] = useState<View>('home'); const [products, setProducts] = useState<Product[]>([]); const [banners, setBanners] = useState<Banner[]>([]); const [categories, setCategories] = useState<Category[]>([]); const [contacts, setContacts] = useState<Contact[]>([]); const [business, setBusiness")
s=s.replace("fetch(`${API}/api/business`).then(r => r.ok ? r.json() : null).catch(() => null)]).then(([nextProducts, nextBanners, nextCategories, nextBusiness])", "fetch(`${API}/api/business`).then(r => r.ok ? r.json() : null).catch(() => null), fetch(`${API}/api/contacts`).then(r => r.ok ? r.json() : []).catch(() => [])]).then(([nextProducts, nextBanners, nextCategories, nextBusiness, nextContacts])")
s=s.replace("setCategories(nextCategories); if (nextBusiness) setBusiness(nextBusiness)", "setCategories(nextCategories); setContacts(nextContacts); if (nextBusiness) setBusiness(nextBusiness)")
s=s.replace("if (view === 'admin') return <Admin products={products} setProducts={setProducts} setView={setView} />", "if (view === 'admin') return <Admin products={products} setProducts={setProducts} setView={setView} />")
s=s.replace("<span className=\"location\">Nairobi · Kenya</span><button className=\"outline-button\"", "<span className=\"location\">Nairobi · Kenya</span>{contacts.filter(contact => contact.active).slice(0, 1).map(contact => <a key={contact.id} className=\"header-contact-link\" href={contactHref(contact)} target={contact.contact_type === 'whatsapp' ? '_blank' : undefined} rel={contact.contact_type === 'whatsapp' ? 'noreferrer' : undefined}>{contact.label}</a>)}<button className=\"outline-button\"")
s=s.replace("<a href=\"#contact\" className=\"text-link\">Speak with a specialist <span>→</span></a>", "<a href=\"#contact\" className=\"text-link\">Speak with a specialist <span>→</span></a></div><ContactActions contacts={contacts} compact />")
s=s.replace("<div className=\"footer-contact\"><p className=\"eyebrow\">Start a conversation</p><a href={`mailto:${business.email}`}>{business.email}</a><a href={`tel:${business.phone.replaceAll(' ', '')}`}>{business.phone}</a></div>", "<div className=\"footer-contact\"><p className=\"eyebrow\">Start a conversation</p><ContactActions contacts={contacts} />{!contacts.length && <><a href={`mailto:${business.email}`}>{business.email}</a><a href={`tel:${business.phone.replaceAll(' ', '')}`}>{business.phone}</a></>}</div>")

marker="function Admin({ products, setProducts, setView }: { products: Product[]; setProducts: (products: Product[]) => void; setView: (view: View) => void }) {"
contact_component="""function ContactManager({ api, token }: { api: string; token: string }) {\n  const empty = { label: '', contact_type: 'whatsapp' as Contact['contact_type'], value: '', display_value: '', active: true, sort_order: 0 };\n  const [items, setItems] = useState<Contact[]>([]); const [form, setForm] = useState(empty); const [editing, setEditing] = useState<number | null>(null); const [busy, setBusy] = useState(false); const [message, setMessage] = useState('');\n  const load = async () => { const response = await fetch(`${api}/api/admin/contacts`, { headers: { Authorization: `Bearer ${token}` } }); if (response.ok) setItems(await response.json()) };\n  useEffect(() => { load().catch(() => setMessage('Could not load contacts.')) }, []);\n  const save = async (event: FormEvent) => { event.preventDefault(); setBusy(true); setMessage(''); try { const response = await fetch(`${api}/api/admin/contacts${editing ? `/${editing}` : ''}`, { method: editing ? 'PUT' : 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify({ ...form, sort_order: Number(form.sort_order) }) }); if (!response.ok) throw new Error(await response.text()); await load(); setForm({ ...empty, sort_order: items.length + 1 }); setEditing(null); setMessage(editing ? 'Contact updated successfully.' : 'Contact added successfully.'); } catch (error) { setMessage(error instanceof Error ? error.message : 'Could not save contact.') } finally { setBusy(false) } };\n  const edit = (item: Contact) => { setEditing(item.id); setForm({ label: item.label, contact_type: item.contact_type, value: item.value, display_value: item.display_value || '', active: item.active, sort_order: item.sort_order }) };\n  const remove = async (item: Contact) => { if (!confirm(`Delete ${item.label}?`)) return; const response = await fetch(`${api}/api/admin/contacts/${item.id}`, { method: 'DELETE', headers: { Authorization: `Bearer ${token}` } }); if (response.ok) setItems(items.filter(current => current.id !== item.id)); };\n  return <section className=\"admin-panel contact-manager\"><div className=\"panel-heading\"><div><p className=\"eyebrow\">Store contacts</p><h2>{editing ? 'Edit contact' : 'Add a contact'}</h2></div></div><form className=\"contact-form\" onSubmit={save}><label>Label<input value={form.label} onChange={e => setForm({ ...form, label: e.target.value })} placeholder=\"Sales WhatsApp\" required /></label><label>Contact type<select value={form.contact_type} onChange={e => setForm({ ...form, contact_type: e.target.value as Contact['contact_type'] })}><option value=\"whatsapp\">WhatsApp</option><option value=\"phone\">Phone call</option><option value=\"sms\">SMS</option><option value=\"email\">Email</option></select></label><label>Number or email<input value={form.value} onChange={e => setForm({ ...form, value: e.target.value })} placeholder=\"254700000000 or sales@kentank.co.ke\" required /></label><label>Display text<input value={form.display_value || ''} onChange={e => setForm({ ...form, display_value: e.target.value })} placeholder=\"+254 700 000 000\" /></label><label>Sort order<input type=\"number\" value={form.sort_order} onChange={e => setForm({ ...form, sort_order: Number(e.target.value) })} /></label><label className=\"checkbox-label\"><input type=\"checkbox\" checked={form.active} onChange={e => setForm({ ...form, active: e.target.checked })} /> Visible on website</label><div className=\"form-actions\"><button className=\"primary-button\" disabled={busy}>{busy ? <Spinner label=\"Saving…\" /> : editing ? 'Update contact' : 'Add contact'}</button>{editing && <button type=\"button\" className=\"secondary-button\" onClick={() => { setEditing(null); setForm({ ...empty, sort_order: items.length + 1 }) }}>Cancel</button>}</div>{message && <div className=\"success-note\">{message}</div>}</form><div className=\"contact-list\">{items.length ? items.map(item => <div className=\"contact-admin-row\" key={item.id}><div><strong>{item.label}</strong><small>{item.contact_type} · {item.display_value || item.value} · {item.active ? 'Visible' : 'Hidden'}</small></div><div><button onClick={() => edit(item)}>Edit</button><button onClick={() => remove(item)}>Delete</button></div></div>) : <div className=\"empty-state\">No contacts configured yet.</div>}</div></section>\n}\n\n"""
s=s.replace(marker, contact_component+marker)
s=s.replace("{['Overview', 'Products', 'Banners', 'Enquiries'].map", "{['Overview', 'Products', 'Banners', 'Contacts', 'Enquiries'].map")
needle="{tab === 'Banners' && <section className=\"admin-panel banner-manager\">"
s=s.replace(needle, "{tab === 'Contacts' && <ContactManager api={API} token={token} />}"+needle)
p.write_text(s)
